import {principleProfiles} from './principle-catalog.js';
// Secondary descriptors of application results from one mouse button.
// Raw signal, derived measurements, and application rules are distinct layers.
// These values are an expandable catalog, never a percentage of all possibilities.
const axisIds = ['context', 'input', 'rule', 'constraint', 'timing', 'effect'];
const value = (id, label, description, scope = 'core', proposal) => ({ id, label, description, scope, ...(proposal ? { proposal } : {}) });
const axis = (id, label, question, description, entries) => ({ id, label, question, description, values: entries.map(entry => value(`${id}.${entry[0]}`, ...entry.slice(1))) });

