function profile(kind, family, summary, focus, tags, explanations, partial = {}) {
  const axes = Object.fromEntries(axisIds.map((id, index) => [id, tags[index].map(tag => `${id}.${tag}`)]));
  const notes = Object.fromEntries(axisIds.map((id, index) => [id, explanations[index]]));
  return { kind, family, summary, focus, axes, ...(Object.keys(partial).length ? { partial: Object.fromEntries(Object.entries(partial).map(([id, tags]) => [id, tags.map(tag => `${id}.${tag}`)])) } : {}), explanations: notes };
}

